import{c as t,Q as n,j as r,m as o}from"./chunks/framework.BqPkuuVc.js";const m=JSON.parse('{"title":"Creating an event from Eventor","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/create-event-from-eventor.md","filePath":"user/event-setup/create-event-from-eventor.md"}'),i={name:"user/event-setup/create-event-from-eventor.md"};function a(s,e,l,h,d,c){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="creating-an-event-from-eventor" tabindex="-1">Creating an event from Eventor <a class="header-anchor" href="#creating-an-event-from-eventor" aria-label="Permalink to &quot;Creating an event from Eventor&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers whose federation uses Eventor for entries.</p><p>How to create a new event by importing it directly from Eventor — classes, competitors, clubs, and start times in one step; just import course files.</p><h2 id="when-to-use-this" tabindex="-1">When to use this <a class="header-anchor" href="#when-to-use-this" aria-label="Permalink to &quot;When to use this&quot;">​</a></h2><p>Use <strong>New from Eventor</strong> when:</p><ul><li>Your federation publishes the event on Eventor and accepts entries there.</li><li>You&#39;ve configured the Eventor connection in <strong>Settings → Eventor</strong>.</li><li>You want classes, competitors, clubs, and (if available) start times pulled in automatically.</li></ul><p>If your event isn&#39;t on Eventor — or you only have IOF XML files — use <a href="./create-event">New Event</a> instead and import data afterwards from <a href="./import-event-data">files</a>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before the <strong>New from Eventor</strong> button will work, configure the connection once in <strong>Settings → Eventor</strong>:</p><ul><li><strong>Host Name</strong> — the URL of your Eventor instance (e.g. <code>https://eventor.orienteering.org.au</code>).</li><li><strong>API Key</strong> — your Eventor API credentials.</li><li><strong>Organisation ID</strong> — your club or federation&#39;s Eventor organisation ID.</li></ul><p>If Eventor isn&#39;t configured, Manager will tell you when you click <strong>New from Eventor</strong> and point you to Settings.</p><h2 id="creating-the-event" tabindex="-1">Creating the event <a class="header-anchor" href="#creating-the-event" aria-label="Permalink to &quot;Creating the event&quot;">​</a></h2><ol><li>On the <strong>Events</strong> page, click <strong>New from Eventor</strong>.</li><li>Manager fetches a list of upcoming events from your organisation. Use the search field to narrow it down by name.</li><li>Select the event you want to import.</li><li>Manager runs through the import in steps and shows progress for each: <ul><li>Fetching event details</li><li>Fetching classes</li><li>Fetching entries</li><li>Fetching start times</li><li>Importing data</li></ul></li><li>When the import finishes you&#39;ll see a summary: <ul><li>Classes imported</li><li>Competitors imported</li><li>Clubs imported</li><li>Start times allocated — or <em>&quot;not yet available&quot;</em> if the draw hasn&#39;t been done on Eventor yet</li></ul></li><li>Click <strong>Open Event</strong> to go to the new event&#39;s dashboard.</li></ol><p>The event is created in <strong>Setup mode</strong> with defaults inherited from <strong>Settings → Event Defaults</strong> — same as any other new event. Only the name, date, discipline, classes, competitors, clubs, and start times come from Eventor.</p><p>The <strong>discipline</strong> comes from the race distance the organiser set on the Eventor event, and covers both the course lengths (Sprint, Middle, Long, Ultra Long) and the competition formats Eventor lists beside them (Knock Out Sprint, Sprint Relay, Mass Start, Pursuit, Relay, Mixed Relay, Qualification, PreO, TempO). Eventor treats Middle as its default, so an event that doesn&#39;t set a distance imports as Middle — change it in the event details if it&#39;s wrong.</p><p>The discipline is a description of the race. It doesn&#39;t make the event a relay on its own — that&#39;s the <strong>event type</strong>, chosen during the import.</p><h2 id="after-import" tabindex="-1">After import <a class="header-anchor" href="#after-import" aria-label="Permalink to &quot;After import&quot;">​</a></h2><p>The event is linked to its Eventor source. That link gives you two things:</p><ul><li><strong>Re-import later</strong> — as entries close and the start list draw is published, you can pull the latest data without searching for the event again. See <a href="./import-event-data#re-importing-from-eventor">Re-importing from Eventor</a>.</li><li><strong>Publish back to it</strong> — the linked event is pre-selected when you upload the <a href="./start-draw#uploading-the-start-list-to-eventor">start list</a> or, after the event, the results.</li><li><strong>Traceability</strong> — the link is recorded on the event so you can see where the data came from.</li></ul><p>You&#39;ll typically want to:</p><ol><li>Open the event details (edit icon on the <strong>Event header</strong> card on the dashboard) and review the name, date, and radio unit numbers. See <a href="./create-event#editing-event-details">Editing event details</a>.</li><li>Import courses separately — Eventor doesn&#39;t carry course definitions. Upload an IOF CourseData XML or Purple Pen file via the <strong>Data Imports</strong> section or the <strong>Import Data</strong> dialog. See <a href="./import-event-data#course-data-iof-coursedata-xml">Importing course data</a>.</li><li>Check the imported data: <ul><li>Open the <strong>Classes</strong> page — confirm the right classes exist (course assignment comes after importing courses).</li><li>Open the <strong>Competitors</strong> page — confirm card numbers and class assignments. Sort by card number to spot blanks.</li><li>If start times were imported, the <strong>Competitors</strong> page shows each competitor&#39;s allocated time and its source.</li></ul></li></ol><h2 id="importing-into-an-existing-event-instead" tabindex="-1">Importing into an existing event instead <a class="header-anchor" href="#importing-into-an-existing-event-instead" aria-label="Permalink to &quot;Importing into an existing event instead&quot;">​</a></h2><p>If you&#39;ve already created an event with <strong>New Event</strong> and want to pull Eventor data into it after the fact — use the <strong>Import Data</strong> dialog from the dashboard. See <a href="./import-event-data#importing-into-an-existing-event">Importing into an existing event</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./create-event">Creating an event</a> — the standard (non-Eventor) flow</li><li><a href="./import-event-data">Importing event data</a> — IOF XML, Purple Pen, and Eventor re-imports</li><li><a href="./../reference/settings">Settings</a> — where the Eventor connection is configured</li><li><a href="./classes-and-courses">Classes and courses</a> — editing what the import created</li><li><a href="./competitors-clubs-teams">Competitors, clubs and teams</a> — editing imported competitors</li><li><a href="./start-times">Start times</a> — how imported start times interact with other sources</li></ul>',25)])])}const p=t(i,[["render",a]]);export{m as __pageData,p as default};
